from collections import defaultdict

EVENTS = [
    {"service": "billing", "status": "open", "minutes": 42},
    {"service": "search", "status": "resolved", "minutes": 7},
    {"service": "billing", "status": "open", "minutes": 11},
    {"service": "search", "status": "open", "minutes": "unknown"},
    {"service": "", "status": "open", "minutes": 5},
]


def valid_event(raw):
    return (
        isinstance(raw, dict)
        and isinstance(raw.get("service"), str)
        and raw["service"].strip()
        and raw.get("status") in {"open", "resolved"}
        and isinstance(raw.get("minutes"), int)
        and raw["minutes"] >= 0
    )


def summarize(events):
    groups = defaultdict(lambda: {"open": 0, "minutes": 0})
    for event in events:
        if not valid_event(event):
            continue
        service = event["service"].strip()
        groups[service]["open"] += event["status"] == "open"
        groups[service]["minutes"] += event["minutes"]

    if not groups:
        return "no valid incidents"

    ordered = sorted(groups.items(), key=lambda item: (-bool(item[1]["open"]), item[0]))
    return "\n".join(
        f"{service}: {data['open']} open, {data['minutes']}m total"
        for service, data in ordered
    )


def main():
    print(summarize(EVENTS))


if __name__ == "__main__":
    main()
